css:
@media print {
    @page {
        size: 76.2mm 297mm;
        margin: 5mm 3mm;
    }
}

/* Encabezados */
.print-format h4, .print-format h5 {
    margin-top: 10px;
    margin-bottom: 0px;
    font-family: "Consolas", monospace;
    color: black;
}

/* Estilo general */
.print-format table,
.print-format tr,
.print-format td,
.print-format th,
.print-format div,
.print-format p {
    padding: 2px !important;
    line-height: 80%;
    vertical-align: middle;
    font-family: "Consolas", monospace;
    font-size: small;
    color: black;
    background-color: white !important;
}

table {
    width: 100%;
    margin: 0;
    border: 0;
}

/* Tabla de items */
table.items {
    border-collapse: collapse;
    width: 100%;
    font-size: medium;
    margin: 0;
    border-spacing: 0;
}

/* Bordes */
table.items thead {
    border-bottom: 0.5px solid black;
}

table.items tbody {
    border-bottom: 0.5px solid black;
}

/* Párrafos */
p {
    margin: -1px 0;
    line-height: 72%;
    color: black;
}

/* Alineaciones */
.text-left {
    text-align: left;
}

.text-right {
    text-align: right;
}

.text-center {
    text-align: center;
}
